Now I understand the situation fully. The fix (GREEN): refactor the two CC=9 inline `file_read` mocks into a shared table-driven factory with CC ≤ 8, preserving exact behavior:

- `var p = args && (args.path || args);` — keeps semantics
- route 1: path contains `ci_violations.json` → return owned snapshot JSON
- route 2: path contains `rework_setup_failed.md` → throw Error('File does not exist')
- route 3: path contains `pr_info.md` → return branch line
- else → null

A table-driven helper:

```js
// Shared file_read mock for the gh-1119 AC6b rejection tests (CC stays ≤ 8 —
// the quality ratchet fails any new function with CRAP > 8).
function makeOwnedGateFileRead(owned) {
   var snapshot = JSON.stringify({ owned: 1, foreign: 0, unknown: 0, violations: owned });
   return function(args) {
       var p = args && (args.path || args);
       var routes = [
           ['ci_violations.json', function() { return snapshot; }],
           ['rework_setup_failed.md', function() { throw new Error('File does not exist'); }],
           ['pr_info.md', function() { return '**Branch**: `bug/PROJ-123` → `develop`'; }]
       ];
       for (var i = 0; i < routes.length; i++) {
           if (p && p.indexOf(routes[i][0]) !== -1) return routes[i][1]();
       }
       return null;
   };
}
``

